from sympy import factorint, primerange

def has_more_than_two_prime_divisors(n):
    return len(factorint(n)) > 2

def find_special_numbers(count):
    found = []
    min_digits = 1
    max_n = 10 ** min_digits
    primes = set(primerange(1, max_n))
    base_numbers = [30, 42, 60, 70, 78, 84, 90, 102, 105]  # Numbers with at least three distinct prime divisors

    while len(found) < count:
        for base in base_numbers:
            for multiplier in range(min_digits, max_n // base):
                n = base * multiplier
                if n in primes:
                    continue
                if has_more_than_two_prime_divisors(n) and (2**n - 8) % n == 0:
                    if not found or len(str(n)) != len(str(found[-1])):
                        found.append(n)
                        if len(found) == count:
                            break
        min_digits += 1
        max_n *= 10
    return found

special_numbers = find_special_numbers(13)
print(special_numbers)
